import React from 'react';

import { MONTH_NAMES_SHORT } from 'utils/timePeriod/timePeriodAvailability';

import {
  MonthLabelSpan,
  MonthLabelsRow,
} from '../../TimePeriodSelector.styles';

interface StaticMonthLabelsProps {
  closedMonthIndex?: number;
  selectedMonthIndexes?: ReadonlyArray<number>;
}

export function StaticMonthLabels({
  closedMonthIndex = 11,
  selectedMonthIndexes = [],
}: Readonly<StaticMonthLabelsProps>) {
  return (
    <MonthLabelsRow>
      {MONTH_NAMES_SHORT.map((month, index) => {
        const selected = selectedMonthIndexes.includes(index);
        const muted = index > closedMonthIndex;

        return (
          <MonthLabelSpan
            key={month}
            $selected={selected}
            $muted={muted}
            data-selected={selected}
            data-muted={muted}
          >
            {month}
          </MonthLabelSpan>
        );
      })}
    </MonthLabelsRow>
  );
}
